#!/usr/bin/env python3
import sqlite3, sys
a = sqlite3.connect("file:data/guidebook.db?mode=ro", uri=True); a.row_factory = sqlite3.Row
b = sqlite3.connect(f"file:{sys.argv[1]}?mode=ro", uri=True); b.row_factory = sqlite3.Row
for t, key in (("evidence_sources", "ref_id"), ("evidence_source_authors", "id")):
    A = {r[key]: dict(r) for r in a.execute(f"select * from {t}")}
    B = {r[key]: dict(r) for r in b.execute(f"select * from {t}")}
    for k in sorted(set(A) | set(B), key=str):
        if A.get(k) != B.get(k):
            if k not in A or k not in B:
                print(t, k, "missing in", "canonical" if k not in A else "rebuilt")
                continue
            d = {c: (str(A[k][c])[:60], str(B[k].get(c))[:60]) for c in A[k] if A[k][c] != B[k].get(c)}
            print(t, k, d)

