"""Compare canonical vs rebuilt DB: row counts for every table, full-row equality for the tables batch 20 wrote."""
import sqlite3, sys
a = sqlite3.connect("file:data/guidebook.db?mode=ro", uri=True)
b = sqlite3.connect(f"file:{sys.argv[1]}?mode=ro", uri=True)
tabs = [t for (t,) in a.execute("select name from sqlite_master where type='table' order by name")]
diff = []
for t in tabs:
    ca = a.execute(f'select count(*) from "{t}"').fetchone()[0]
    try:
        cb = b.execute(f'select count(*) from "{t}"').fetchone()[0]
    except Exception as e:
        cb = f"ERR {e}"
    if ca != cb:
        diff.append((t, ca, cb))
