#!/usr/bin/env python3
"""Find the Internet Archive requests batch 19 made for Templer, with the tool results."""
import json
import re
import sys

for path in sys.argv[1:]:
    uses = {}
    for line in open(path, encoding="utf-8"):
        try:
            d = json.loads(line)
        except ValueError:
            continue
        m = d.get("message") or {}
        c = m.get("content")
        if not isinstance(c, list):
            continue
        for x in c:
            if not isinstance(x, dict):
                continue
            if x.get("type") == "tool_use":
                s = json.dumps(x.get("input", {}))
                if "archive.org" in s and re.search(r"templer|provisions", s, re.I):
                    uses[x["id"]] = (d.get("timestamp"), s[:900])
            if x.get("type") == "tool_result" and x.get("tool_use_id") in uses:
                cont = x.get("content")
                txt = cont if isinstance(cont, str) else " ".join(
                    y.get("text", "") for y in cont if isinstance(y, dict))
                ts, s = uses[x["tool_use_id"]]
                print("=====", path.split("/")[-1], ts)
                print("CALL:", s)
                print("RESULT:", txt[:1200])

