#!/usr/bin/env python3
"""Print full call + result for the adversarial subagent's tool uses between two timestamps."""
import json
import sys

path, t0, t1 = sys.argv[1], sys.argv[2], sys.argv[3]
uses = {}
for line in open(path, encoding="utf-8"):
    try:
        d = json.loads(line)
    except ValueError:
        continue
    ts = d.get("timestamp") or ""
    m = d.get("message") or {}
    c = m.get("content")
    if not isinstance(c, list):
        continue
    for x in c:
        if not isinstance(x, dict):
            continue
        if x.get("type") == "tool_use" and t0 <= ts <= t1:
            uses[x["id"]] = (ts, json.dumps(x.get("input", {}))[:3000])
        if x.get("type") == "tool_result" and x.get("tool_use_id") in uses:
            cont = x.get("content")
            txt = cont if isinstance(cont, str) else " ".join(
                y.get("text", "") for y in cont if isinstance(y, dict))
            ts0, s = uses[x["tool_use_id"]]
            print("=====", ts0)
            print("CALL:", s)
            print("RESULT:", txt[:3000])
    if m.get("role") == "assistant" and t0 <= ts <= t1:
        for x in c:
            if isinstance(x, dict) and x.get("type") == "text":
                print("TEXT:", ts, x["text"][:600])

